begin;
-- Apenas registros temporários; rollback garante nenhum estoque fictício no piloto.
set local role authenticated;
do $$
declare actor uuid; stranger uuid;spec jsonb;r jsonb;req uuid:=gen_random_uuid();a uuid;b uuid;c uuid;s uuid;d date:=(now()at time zone'America/Manaus')::date-1;n bigint;
begin
-- IDs dos perfis são encontrados, não alterados.
select id into actor from public.profiles where full_name='Vitor Amaral';
select id into stranger from public.profiles where id<>actor and role='employee' limit 1;
perform set_config('request.jwt.claim.sub',stranger::text,true);
assert (public.invd_context()->>'allowed')::boolean=false,'perfil estranho autorizado';
begin perform public.invd_list();raise exception 'Leitura não autorizada';exception when insufficient_privilege then null;end;
begin perform public.invd_command('catalog_add',gen_random_uuid(),'{"category":"warehouse","value":"QA"}');raise exception 'Escrita não autorizada';exception when insufficient_privilege then null;end;
perform set_config('request.jwt.claim.sub',actor::text,true);
assert (public.invd_context()->>'allowed')::boolean,'Vitor sem acesso';
assert not (public.invd_context()->>'can_manage')::boolean,'Vitor gerencia indevidamente';
begin insert into public.inventarydaily_table(kind)values('box');raise exception 'INSERT direto indevido';exception when insufficient_privilege then null;end;
begin update public.inventarydaily_table set data='{}' where kind='access';raise exception 'UPDATE direto indevido';exception when insufficient_privilege then null;end;
begin delete from public.inventarydaily_table where kind='access';raise exception 'DELETE direto indevido';exception when insufficient_privilege then null;end;
perform public.invd_command('catalog_add',gen_random_uuid(),'{"category":"warehouse","value":"QA A"}');
perform public.invd_command('catalog_add',gen_random_uuid(),'{"category":"warehouse","value":"QA B"}');
spec:='{"invoice":"QA-rollback","type":"Comum","color":"Incolor","thickness_mm":4,"width_mm":2000,"height_mm":1000,"sheets":10,"damaged":1,"warehouse":"QA A"}';
r:=public.invd_command('box_create',req,jsonb_build_object('items',jsonb_build_array(spec,spec||'{"warehouse":"QA B"}',spec)));
a:=(r->'ids'->>0)::uuid;b:=(r->'ids'->>1)::uuid;c:=(r->'ids'->>2)::uuid;
assert public.invd_command('box_create',req,jsonb_build_object('items',jsonb_build_array(spec,spec||'{"warehouse":"QA B"}',spec)))=r,'retry alterou resultado';
begin perform public.invd_command('box_create',req,jsonb_build_object('items',jsonb_build_array(spec)));raise exception 'UUID reutilizado payload diferente';exception when raise_exception then if sqlerrm='UUID reutilizado payload diferente'then raise;end if;end;
select count(*)into n from public.inventarydaily_table where kind='box';
begin perform public.invd_command('box_create',gen_random_uuid(),jsonb_build_object('items',jsonb_build_array(spec,spec||'{"sheets":0}')));raise exception 'Lote inválido aceito';exception when raise_exception then if sqlerrm='Lote inválido aceito'then raise;end if;end;
assert(select count(*)from public.inventarydaily_table where kind='box')=n,'lote inseriu parcial';
r:=public.invd_command('inventory_start',gen_random_uuid(),jsonb_build_object('date',d));s:=(r->>'id')::uuid;
begin perform public.invd_command('box_create',gen_random_uuid(),jsonb_build_object('items',jsonb_build_array(spec)));raise exception 'Entrada em contagem permitida';exception when raise_exception then if sqlerrm='Entrada em contagem permitida'then raise;end if;end;
begin perform public.invd_command('inventory_scan',gen_random_uuid(),jsonb_build_object('inventory_id',s,'code',gen_random_uuid()));raise exception 'Caixa inexistente escaneada';exception when raise_exception then if sqlerrm='Caixa inexistente escaneada'then raise;end if;end;
perform public.invd_command('inventory_scan',gen_random_uuid(),jsonb_build_object('inventory_id',s,'code',b));
perform public.invd_command('inventory_scan',gen_random_uuid(),jsonb_build_object('inventory_id',s,'code',b));
assert(select count(*)from public.inventarydaily_table where parent_id=s and kind='scan')=1,'leitura duplicou';
begin perform public.invd_command('inventory_finish',gen_random_uuid(),jsonb_build_object('inventory_id',s,'confirmed_warehouses',jsonb_build_array('QA A','QA B')));raise exception 'Finalizou pendente';exception when raise_exception then if sqlerrm='Finalizou pendente'then raise;end if;end;
perform public.invd_command('inventory_loose',gen_random_uuid(),spec||jsonb_build_object('inventory_id',s,'quantity',6));
assert(select data->>'status'from public.inventarydaily_table where id=a)='sealed','abriu por inferência sem validação';
perform public.invd_command('inventory_decide',gen_random_uuid(),jsonb_build_object('inventory_id',s,'box_id',a,'outcome','opened'));
perform public.invd_command('inventory_decide',gen_random_uuid(),jsonb_build_object('inventory_id',s,'box_id',c,'outcome','missing','notes','Não localizada na conferência QA'));
begin perform public.invd_command('inventory_finish',gen_random_uuid(),jsonb_build_object('inventory_id',s,'confirmed_warehouses',jsonb_build_array('QA A')));raise exception 'Finalizou sem galpão';exception when raise_exception then if sqlerrm='Finalizou sem galpão'then raise;end if;end;
r:=public.invd_command('inventory_finish',gen_random_uuid(),jsonb_build_object('inventory_id',s,'confirmed_warehouses',jsonb_build_array('QA A','QA B')));
assert(r->'summary'->>'total_sheets')::numeric=16,'chapas totais';
assert(r->'summary'->>'total_m2')::numeric=32,'m² totais';
assert(r->'summary'->>'sealed_damaged')::numeric=1,'avarias caixa';
assert(r->'summary'->>'loose_damaged')::numeric=1,'avarias avulsas';
assert(r->'summary'->>'missing_boxes')::numeric=1,'missing sum';
assert(select data->>'status'from public.inventarydaily_table where id=a)='opened','aberta não persistiu';
assert(select data->>'status'from public.inventarydaily_table where id=c)='missing','não localizada somaria ao físico';
begin perform public.invd_command('inventory_loose',gen_random_uuid(),spec||jsonb_build_object('inventory_id',s,'quantity',6));raise exception 'Alterou inventário encerrado';exception when raise_exception then if sqlerrm='Alterou inventário encerrado'then raise;end if;end;
r:=public.invd_command('inventory_start',gen_random_uuid(),jsonb_build_object('date',d+1));s:=(r->>'id')::uuid;
assert(select jsonb_array_length(data->'expected')from public.inventarydaily_table where id=s)=2,'nova contagem inclui aberta ou omite missing';
perform public.invd_command('inventory_scan',gen_random_uuid(),jsonb_build_object('inventory_id',s,'code',c));
perform public.invd_command('inventory_scan',gen_random_uuid(),jsonb_build_object('inventory_id',s,'code',b));
r:=public.invd_command('inventory_finish',gen_random_uuid(),jsonb_build_object('inventory_id',s,'confirmed_warehouses',jsonb_build_array('QA A','QA B')));
assert(r->'summary'->>'loose_sheets')::numeric=0,'avulsas acumularam de ontem';
assert(select data->>'status'from public.inventarydaily_table where id=c)='sealed','reencontrada não restaurou';
assert not exists(select 1 from jsonb_array_elements(public.invd_list())x where x->>'kind' in('log','access')),'operador leu auditoria/acessos';
end$$;
reset role;
select 'PASS: acesso profiles, RPC/RLS, idempotência, lote atômico, snapshot, duplicidade, abertura explícita, m²/avarias, missing e diário sem acumular.' as resultado;
rollback;
